WITH lines AS (SELECT id, customer_id, coupon_codes, INLINE(items) FROM carts) SELECT promo, customer_id, COUNT(CASE WHEN promo = 'WELCOME5' THEN 1 END) AS welcome5_count, APPROX_PERCENTILE(qty, ARRAY(0.25, 0.5, 0.75)) AS qty_quartiles, MAX(qty) FILTER (WHERE promo = 'SPRING10') AS spring10_max_qty, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN promo = 'VIP' THEN 1 END), 0), 2) AS price_per_vip, COUNT(*) AS num_rows, COUNT(*) FILTER (WHERE promo = 'BUNDLE') AS bundle_rows FROM lines GROUP BY GROUPING SETS ((promo, customer_id), (promo)) ORDER BY customer_id ASC;
